// Package: AWSSDK.Lambda
using Amazon.Lambda;
using Amazon.Lambda.Model;

var lambdaClient = new AmazonLambdaClient(RegionEndpoint.USEast1);

var createRequest = new CreateFunctionRequest
{
    FunctionName = "aspnet-process-order",
    Runtime = Runtime.Dotnet8,
    Role = "arn:aws:iam::123456789012:role/lambda-execution-role",
    Handler = "AssemblyName::Namespace.ClassName::FunctionHandler",
    Code = new FunctionCode
    {
        ZipFile = File.ReadAllBytes("bin/Release/net8.0/publish/function.zip")
    },
    Description = "Processes an order from an SQS event."
};

var createResponse = await lambdaClient.CreateFunctionAsync(createRequest);
Console.WriteLine($"Function ARN: {createResponse.FunctionArn}");

var invokeRequest = new InvokeRequest
{
    FunctionName = "aspnet-process-order",
    Payload = "{\"orderId\":1001,\"customerId\":42,\"total\":59.99}"
};

var invokeResponse = await lambdaClient.InvokeAsync(invokeRequest);
using var reader = new StreamReader(invokeResponse.Payload);
string result = await reader.ReadToEndAsync();
Console.WriteLine($"Response: {result}");

if (invokeResponse.FunctionError != null)
{
    Console.WriteLine($"Error: {invokeResponse.FunctionError}");
}
